/**
 * Dutch translations for all DSH built-in i18n namespaces.
 *
 * Translation conventions:
 * - Formal "u" form for user-facing text.
 * - Technical loanwords stay in English (Git, SSH, HTTP, URL, Markdown, PDF, VS Code).
 * - Placeholders keep `{name}` verbatim (interpolation runs after lookup).
 * - Welcome-notice copy (settings.models.welcome*) is inlined from
 *   WELCOME_NOTICE_COPY in onboarding-copy.ts.
 */
export declare const dicts: Record<string, Record<string, string>>;
